<div x-data @open-booking.window="const data = $event.detail || {}; const url = new URL(@js(route('bookings.create')), window.location.origin); for (const [key, value] of Object.entries({check_in: data.checkIn, check_out: data.checkOut, adults: data.adults, children: data.children, room: data.room})) { if(value !== undefined &amp;&amp; value !== '') url.searchParams.set(key, value); } window.location.assign(url.toString());"></div>
